    'Analisis_Spasial_Transnasionalisme_dan_Resiliensi_Sosio_Kultural' => 'Analisis Spasial, Transnasionalisme, dan Resiliensi Sosio-Kultural',
    '_p_style_text_align_justify_span_style_color_rgb_255_255_255_Kajian_terhadap_historiografi_Kabupaten_Garut_menyajikan_sebuah_diskursus_yang_sangat_mendalam_dan_multidimensional_mengenai_bagaimana_sebuah_entitas_administratif_di_wilayah_dataran_tinggi_Priangan_Jawa_Barat_bertransformasi_melewati_berbagai_epos_sejarah_yang_krusial_dan_bergejolak_Garut_bukan_sekadar_wilayah_penyangga_geografis_yang_pasif_ia_merupakan_episentrum_yang_secara_aktif_berpartisipasi_dalam_berbagai_peristiwa_lintas_negara_mulai_dari_penetrasi_awal_era_kolonialisme_Hindia_Belanda_periode_komodifikasi_pariwisata_global_pada_awal_abad_ke_20_palagan_revolusi_fisik_kemerdekaan_yang_berdarah_hingga_fase_konsolidasi_identitas_nasional_pasca_kolonial_span_br_p_' => '<p style="text-align: justify; "><span style="color: rgb(255, 255, 255);">Kajian terhadap historiografi Kabupaten Garut menyajikan sebuah diskursus yang sangat mendalam dan multidimensional mengenai bagaimana sebuah entitas administratif di wilayah dataran tinggi Priangan, Jawa Barat, bertransformasi melewati berbagai epos sejarah yang krusial dan bergejolak. Garut bukan sekadar wilayah penyangga geografis yang pasif; ia merupakan episentrum yang secara aktif berpartisipasi dalam berbagai peristiwa lintas negara, mulai dari penetrasi awal era kolonialisme Hindia Belanda, periode komodifikasi pariwisata global pada awal abad ke-20, palagan revolusi fisik kemerdekaan yang berdarah, hingga fase konsolidasi identitas nasional pasca-kolonial.</span><br /></p>',
    'Api_Revolusi_di_Dataran_Tinggi_Priangan' => 'Api Revolusi di Dataran Tinggi Priangan',
    'Revitalisasi_Peran_Garut_Pasca_Bumi_Hangus_Bandung_Lautan_Api_1946_' => 'Revitalisasi Peran Garut Pasca-Bumi Hangus "Bandung Lautan Api" (1946)',
    '_p_style_text_align_left_Peristiwa_monumental_span_style_font_weight_bold_Bandung_Lautan_Api_span_yang_meletus_pada_23_Maret_1946_memaksa_ratusan_ribu_penduduk_sipil_bersama_barisan_Tentara_Republik_Indonesia_TRI_untuk_membumihanguskan_infrastruktur_kota_Bandung_Taktik_drastis_ini_bertujuan_agar_kekuatan_militer_Sekutu_dan_rezim_NICA_tidak_dapat_memanfaatkan_fasilitas_strategis_tersebut_Gelombang_eksodus_dan_armada_laskar_pejuang_terpaksa_mundur_secara_taktis_ke_wilayah_selatan_yang_secara_instan_menempatkan_Kabupaten_Garut_sebagai_basis_benteng_pertahanan_utama_dan_komando_pusat_operasi_perang_gerilya_Lanskap_topografi_pegunungan_Garut_yang_terjal_berfungsi_sebagai_pelindung_benteng_alami_bagi_laskar_pejuang_termasuk_di_dalamnya_kekuatan_milisi_Laskar_Hizbullah_dalam_menyusun_dan_melancarkan_serangan_balasan_yang_asimetris_demi_mempertahankan_kedaulatan_kemerdekaan_Indonesia_br_p_' => '<p style="text-align: left;">Peristiwa monumental "<span style="font-weight: bold;">Bandung Lautan Api</span>" yang meletus pada 23 Maret 1946 memaksa ratusan ribu penduduk sipil bersama barisan Tentara Republik Indonesia (TRI) untuk membumihanguskan infrastruktur kota Bandung. Taktik drastis ini bertujuan agar kekuatan militer Sekutu dan rezim NICA tidak dapat memanfaatkan fasilitas strategis tersebut. Gelombang eksodus dan armada laskar pejuang terpaksa mundur secara taktis ke wilayah selatan, yang secara instan menempatkan Kabupaten Garut sebagai basis benteng pertahanan utama dan komando pusat operasi perang gerilya. Lanskap topografi pegunungan Garut yang terjal berfungsi sebagai pelindung benteng alami bagi laskar pejuang—termasuk di dalamnya kekuatan milisi Laskar Hizbullah—dalam menyusun dan melancarkan serangan balasan yang asimetris demi mempertahankan kedaulatan kemerdekaan Indonesia.<br /></p>',
    'Wajah_Klasik_Garut_Tata_Ruang_dan_Anatomi_Kekuasaan' => 'Wajah Klasik Garut: Tata Ruang dan Anatomi Kekuasaan',
    'Dinamika_Kehidupan_di_Alun_Alun_Garut_pada_Era_Hindia_Belanda_1890_1920_' => 'Dinamika Kehidupan di Alun-Alun Garut pada Era Hindia Belanda (1890-1920)',
    '_p_style_text_align_justify_Sejarah_pembentukan_Kabupaten_Garut_mencerminkan_dinamika_administratif_yang_kompleks_dengan_rujukan_pembentukan_wilayah_antara_tahun_1813_hingga_pembangunan_Jembatan_Leuwidaun_pada_1918_Dokumen_arsip_visual_dari_pergantian_abad_ke_20_memperlihatkan_Alun_alun_Garut_bukan_sekadar_ruang_kosong_melainkan_pusat_interaksi_sosial_politik_dan_keagamaan_yang_krusial_Di_kawasan_ini_terintegrasi_bangunan_bersejarah_Babancong_Masjid_Agung_Garut_kediaman_resmi_Bupati_hingga_monumen_kolonial_K_F_Holle_Dengan_latar_belakang_siluet_megah_Gunung_Cikuray_tata_ruang_ini_merepresentasikan_perpaduan_yang_sarat_makna_antara_sistem_kosmologi_pemerintahan_tradisional_Sunda_dan_intervensi_arsitektural_pemerintah_kolonial_br_p_' => '<p style="text-align: justify;">Sejarah pembentukan Kabupaten Garut mencerminkan dinamika administratif yang kompleks, dengan rujukan pembentukan wilayah antara tahun 1813 hingga pembangunan Jembatan Leuwidaun pada 1918. Dokumen arsip visual dari pergantian abad ke-20 memperlihatkan Alun-alun Garut bukan sekadar ruang kosong, melainkan pusat interaksi sosial, politik, dan keagamaan yang krusial. Di kawasan ini terintegrasi bangunan bersejarah Babancong, Masjid Agung Garut, kediaman resmi Bupati, hingga monumen kolonial K.F. Holle. Dengan latar belakang siluet megah Gunung Cikuray, tata ruang ini merepresentasikan perpaduan yang sarat makna antara sistem kosmologi pemerintahan tradisional Sunda dan intervensi arsitektural pemerintah kolonial.<br /></p>',
    'Menyaksikan_Masa_Lalu_Asal_Usul_dan_Evolusi_Kabupaten_Garut' => 'Menyaksikan Masa Lalu: Asal-Usul dan Evolusi Kabupaten Garut',
    'Kumpulan_dokumentasi_audiovisual_dan_ulasan_sejarah_mendalam_mengenai_proses_lahir_dan_berkembangnya_wilayah_Garut_' => 'Kumpulan dokumentasi audiovisual dan ulasan sejarah mendalam mengenai proses lahir dan berkembangnya wilayah Garut.',
    '_p_p_div_style_text_align_justify_Konten_video_ini_dirancang_bagi_audiens_yang_menyukai_pendekatan_storytelling_secara_visual_Narasi_di_dalam_video_akan_mengupas_sejarah_secara_tuntas_mulai_dari_sejarah_pembubaran_Kabupaten_Limbangan_oleh_Daendels_asal_usul_penamaan_kota_Garut_yang_konon_berasal_dari_kata_Kakarut_tergores_jejak_awal_penyebaran_agama_Islam_di_wilayah_tersebut_hingga_cuplikan_video_langka_perbandingan_sudut_sudut_kota_Garut_di_masa_kolonial_versus_masa_kini_Then_and_Now_div_' => '<p></p>
<div style="text-align: justify;">Konten video ini dirancang bagi audiens yang menyukai pendekatan storytelling secara visual. Narasi di dalam video akan mengupas sejarah secara tuntas—mulai dari sejarah pembubaran Kabupaten Limbangan oleh Daendels, asal-usul penamaan kota Garut yang konon berasal dari kata Kakarut (tergores), jejak awal penyebaran agama Islam di wilayah tersebut, hingga cuplikan video langka perbandingan sudut-sudut kota Garut di masa kolonial versus masa kini (Then and Now).</div>',
    'Memori_Hitam_Putih_Melacak_Kejayaan_Swiss_van_Java_di_Era_Kolonial' => 'Memori Hitam Putih: Melacak Kejayaan "Swiss van Java" di Era Kolonial',
    'Napak_tilas_keindahan_tata_kota_dan_kehidupan_masyarakat_Kabupaten_Garut_tempo_dulu_yang_memikat_hati_bangsa_Eropa_' => 'Napak tilas keindahan tata kota dan kehidupan masyarakat Kabupaten Garut tempo dulu yang memikat hati bangsa Eropa.',
    '_p_style_text_align_justify_Konten_carousel_ini_akan_membawa_audiens_bernostalgia_melihat_wajah_Kabupaten_Garut_di_masa_lampau_Konten_ini_menceritakan_jejak_Garut_sejak_masa_kolonial_Belanda_mulai_dari_tata_ruang_kotanya_yang_asri_suasana_stasiun_kereta_api_bersejarah_yang_bahkan_pernah_dikunjungi_oleh_komedian_legendaris_Charlie_Chaplin_pada_tahun_1920_an_hingga_potret_aktivitas_masyarakat_lokal_Visual_ini_menjadi_bukti_sejarah_mengapa_Garut_dulunya_menjadi_kota_peristirahatan_paling_prestisius_bagi_kaum_elite_Eropa_di_Hindia_Belanda_br_p_' => '<p style="text-align: justify; ">Konten carousel ini akan membawa audiens bernostalgia melihat wajah Kabupaten Garut di masa lampau. Konten ini menceritakan jejak Garut sejak masa kolonial Belanda, mulai dari tata ruang kotanya yang asri, suasana stasiun kereta api bersejarah (yang bahkan pernah dikunjungi oleh komedian legendaris Charlie Chaplin pada tahun 1920-an), hingga potret aktivitas masyarakat lokal. Visual ini menjadi bukti sejarah mengapa Garut dulunya menjadi kota peristirahatan paling prestisius bagi kaum elite Eropa di Hindia Belanda.<br /></p>',
    'Video_Edukasi_Sejarah_Wilayah_Jawa_Barat_Bandung_Lautan_Api_' => 'Video Edukasi Sejarah Wilayah Jawa Barat & Bandung Lautan Api.',
